STYLE=ParagraphStyle('body',fontName='Helvetica',fontSize=10.3,leading=15,textColor=HexColor(DARK))
def para(c,text,x,y,width,size=10.3,color=DARK,bold=False):
 style=ParagraphStyle('p',parent=STYLE,fontName='Helvetica-Bold' if bold else 'Helvetica',fontSize=size,leading=size*1.45,textColor=HexColor(color))
 p=Paragraph(escape(text),style); _,height=p.wrap(width,900); p.drawOn(c,x,y-height); return y-height

def page(c,role,num,title,kicker):
 c.setFillColor(white);c.rect(0,0,W,H,fill=1,stroke=0)
 c.drawImage(str(ROOT/'ia_maturity/public/images/alphax_logo.png'),40,H-67,width=104,height=57,mask='auto',preserveAspectRatio=True)
 c.setFillColor(HexColor(GRAY));c.setFont('Helvetica',9);c.drawRightString(W-40,H-39,'GRC  /  '+role+' guide')
 c.setStrokeColor(HexColor('#e2e7ec'));c.line(40,H-81,W-40,H-81)
 para(c,kicker.upper(),40,H-105,510,9,BLUE,True)
 para(c,title,40,H-127,510,26,DARK,True)
 c.setFillColor(HexColor(BLUE));c.rect(40,44,28,3,fill=1,stroke=0)
 c.setFont('Helvetica',8);c.setFillColor(HexColor(GRAY));c.drawString(40,29,'AlphaX GRC | IRSAA Business Solutions | App v2.16.1 | 11 Nov 2026');c.drawRightString(W-40,29,f'{num} / 5')

def note(c,title,text,y):
 c.setFillColor(HexColor(PALE));c.roundRect(40,y-84,W-80,84,8,fill=1,stroke=0)
 para(c,title,54,y-12,W-108,10.5,BLUE,True);para(c,text,54,y-32,W-108,10)

def steps_page(c,d,num,items):
 page(c,d['title'],num,'Your step-by-step guide','Do this in the app')
 y=H-185
 for title,where,steps in items:
  y=para(c,title,40,y,W-80,15,BLUE,True)-4
  y=para(c,'WHERE  '+where,40,y,W-80,9,GRAY,True)-10
  for i,s in enumerate(steps,1):
   c.setFillColor(HexColor(BLUE));c.circle(48,y-7,8,fill=1,stroke=0);c.setFillColor(white);c.setFont('Helvetica-Bold',8);c.drawCentredString(48,y-10,str(i))
   y=para(c,s,65,y,W-105,10)-7
  y-=14
 assert y>55,(d['title'],num,y)
 c.showPage()

def flow(c,role):
 page(c,role,2,'The whole journey','Who does what next?')
 nodes=[('ADMIN + MANAGER','Prepare active templates and publish package choices'),('AUDITOR / CONSULTANT + CUSTOMER','Invite or register; verify email and complete onboarding'),('CUSTOMER + ALLOCATED TEAM','Choose assessment type, template and confirmed scope'),('CUSTOMER / PERMITTED CONTRIBUTOR','Answer included questions and submit required evidence'),('ALLOCATED CONSULTANT / REVIEWER','Review; request clarification if answers need changes'),('ALLOCATED REVIEWER / ADMIN','Approve and release the report'),('CUSTOMER + ASSIGNED STAFF','Read available results and track improvement actions')]
 y=H-193
 for i,(actor,text) in enumerate(nodes):
  c.setFillColor(HexColor(PALE if i%2==0 else '#f5f7fa'));c.roundRect(64,y-52,445,52,7,fill=1,stroke=0)
  para(c,actor,78,y-7,415,8,BLUE,True);para(c,text,78,y-23,415,10.5)
  if i<6:
   c.setStrokeColor(HexColor(BLUE));c.setLineWidth(1.3);c.line(286,y-53,286,y-67);c.line(286,y-67,282,y-63);c.line(286,y-67,290,y-63)
  y-=70
 note(c,'If a step needs another person','Clarification returns to the customer, then back to review. Operational approvals can pause onboarding. Only actions allowed by your role and allocation are shown.',y+3)
 c.showPage()

for key,d in DATA.items():
 file=OUT/f'AlphaX-GRC-{d["title"]}-Guide.pdf';c=canvas.Canvas(str(file),pagesize=(W,H));c.setTitle('AlphaX GRC | '+d['title']+' easy guide');c.setAuthor('AlphaX | IRSAA Business Solutions')
 page(c,d['title'],1,d['title']+' guide','Simple steps. Clear responsibilities.')
 y=para(c,d['intro'],40,H-190,W-80,15)-23
 y=para(c,'What you can do',40,y,W-80,13,BLUE,True)-6;y=para(c,d['can'],40,y,W-80)-20
 y=para(c,'Where to go',40,y,W-80,13,BLUE,True)-10
 for label,desc in d['menus']:
  c.setStrokeColor(HexColor('#e2e7ec'));c.line(40,y+3,W-40,y+3)
  a=para(c,label,40,y-5,217,10,BLUE,True);b=para(c,desc,273,y-5,282,10);y=min(a,b)-16
 note(c,'Your access matters',d['limit'],y-2)
 para(c,'Read this guide: 1 Overview  |  2 Full flow  |  3-4 Steps  |  5 Quick help',40,83,W-80,9,GRAY)
 c.showPage();flow(c,d['title']);steps_page(c,d,3,d['tasks'][:3]);steps_page(c,d,4,d['tasks'][3:])
 page(c,d['title'],5,'Quick help & next steps','Keep this page nearby')
 y=H-190
 for problem,answer in d['checks']:
  y=para(c,problem,40,y,W-80,13,BLUE,True)-5;y=para(c,answer,40,y,W-80,11)-23
 y=para(c,'Finding your way',40,y,W-80,13,BLUE,True)-7
 y=para(c,'Use the left sidebar on a computer, or the menu button on a phone. Open Help & guides from the workspace header. Use the page tour to learn the controls without changing records.',40,y,W-80,11)-16
 y=para(c,'Menu names in this guide use English. The app also offers Arabic. Available buttons depend on your role, customer access, assessment allocation and current state.',40,y,W-80,10,GRAY)-18
 note(c,'A useful support request','Share the page name, assessment or invitation reference, current status and the action you were trying to take. Never share passwords, verification codes or invitation links.',y)
 c.showPage();c.save();print(file.name)
with zipfile.ZipFile(OUT/'AlphaX-GRC-Role-Guides.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in sorted(OUT.glob('*.pdf')): z.write(f,f.name)
